'use strict';

function caseDiagram(sectionId) {
  function reference(id, label) {
    return `<button type="button" class="case-reference" data-source="${esc(id)}">${esc(label)}</button>`;
  }

  function node(title, detail) {
    return `<div class="case-node"><strong>${esc(title)}</strong><span>${esc(detail)}</span></div>`;
  }

  function arrow(label) {
    return `<div class="case-arrow"><span>${esc(label)}</span><i aria-hidden="true"></i></div>`;
  }

  function plate(title, body, citations) {
    const headingId = `case-diagram-${sectionId}`;
    return `<figure class="case-diagram case-${sectionId}" aria-labelledby="${headingId}">
      <h2 id="${headingId}">${esc(title)}</h2>
      ${body}
      <figcaption class="case-references">${citations}</figcaption>
    </figure>`;
  }

  if (sectionId === 'cotton') {
    return plate('Who financed the mills? Who supplied their looms?', `
      <div class="case-lanes">
        <div class="case-lane">
          ${node('Rock Hill and Charleston residents', 'South Carolina · 1882')}
          ${arrow('held shares in')}
          ${node('Rock Hill cotton factory', 'Rock Hill residents held $85,000 of its $100,000 in stock.')}
        </div>
        <div class="case-lane case-second">
          ${node('Draper Company', 'Hopedale, Massachusetts · 1905 catalog')}
          ${arrow('supplied looms to')}
          ${node('Gaffney and Pelzer mills', 'Draper listed customers in both South Carolina towns.')}
        </div>
      </div>
      <p class="case-note">The customer list leaves the supplier of Rock Hill’s looms unidentified.</p>`,
    reference('mitchell1918', 'Shares · Mitchell 1918, 149, 152') +
    reference('draper1905', 'Looms · Draper 1905, PDF 229, 233, 236'));
  }

  if (sectionId === 'pipe') {
    return plate('Two routes to centrifugal casting in Birmingham', `
      <div class="case-fork">
        <div class="case-fork-root"><strong>Birmingham</strong><span>Two separate foundries</span></div>
        <div class="case-fork-branches">
          <div class="case-branch">
            ${node('American Cast Iron Pipe Company', 'William D. Moore tested a sand-lined mold in 1922.')}
            ${arrow('developed locally')}
            ${node('Mono-Cast shop', 'Opened in Birmingham in 1926.')}
          </div>
          <div class="case-branch case-second">
            ${node('United States Cast Iron Pipe & Foundry', 'Bought exclusive US rights to the Brazilian process in 1921.')}
            ${arrow('introduced first at Burlington, NJ')}
            ${node('Birmingham works', 'Adopted it next. Bessemer followed in 1934.')}
          </div>
        </div>
      </div>`,
    reference('us-pipe-haer', 'Plant histories · O’Connor 1996, 24–32') +
    reference('delavaud1916', 'Brazilian process · Sensaud de Lavaud & Arens 1916, fig. 1'));
  }

  if (sectionId === 'cigarettes') {
    return plate('Who owned the machines, and who made them pay?', `
      <div class="case-chain">
        ${node('Bonsack Machine Company', 'Retained ownership of the machines.')}
        ${arrow('leased machines to')}
        ${node('Duke in Durham', 'Duke’s mechanics improved how the leased machines ran.')}
        ${arrow('reached buyers through')}
        ${node('City sales offices', 'New York also gave Duke access to advertising services.')}
      </div>
      <p class="case-note"><strong>1885 lease</strong> Duke paid 24¢ per thousand cigarettes. The usual rate was 30¢ or 33¢. A later clause kept Duke’s rate a quarter below any rival’s. The discount applied to every batch he made.</p>`,
    reference('porter1969', 'Lease and sales · Porter 1969, 64–70') +
    reference('bonsack1881', 'Mechanism · Bonsack 1881, specification 1'));
  }

  return '';
}

