// Each diagram follows the reading order of the evidence it compares.
function synthesisDiagram(sectionId) {
  function cite(id, label) {
    return '<button type="button" class="citation syn-source" data-source="' + id + '">' + label + '</button>';
  }

  if (sectionId === 'institutions') {
    const groups = [
      ['Commercial agreements', [
        ['Shares for machinery', 'Machinery suppliers',
          'Suppliers often sold the shares they accepted as payment. A later shareholder list could therefore miss the firm that originally equipped a mill. At Loray Mill the machinery makers retained most preferred stock after reorganization.',
          cite('mitchell1918', 'Mitchell 1918, 205–15')],
        ['Credit against cloth sales', 'Commission houses',
          'A loan could give the lender the right to sell a mill’s cloth for years. Even after the owners had installed the looms and hired weavers, the commission house could still handle the sale of what they wove.',
          cite('mitchell1918', 'Mitchell 1918, 205–15')],
        ['Exclusive US process rights', 'US Cast Iron Pipe &amp; Foundry',
          'The company chose which plant received the de Lavaud process first. A rival Birmingham foundry developed its own process.',
          cite('us-pipe-haer', 'O’Connor 1996, 24, 27–32')],
        ['Lease priced by output', 'Bonsack and Duke',
          'Bonsack owned the machines and charged Duke per thousand cigarettes. Duke’s mechanics improved how they ran. Ownership of those improvements remains unclear.',
          cite('porter1969', 'Porter 1969, 67–69')]
      ]],
      ['Laws', [
        ['Tax exemptions', 'South Carolina and Georgia',
          'South Carolina gave ten years’ relief on new factory machinery. Georgia’s 1872 law gave cotton and woolen mills ten years. How much investment the exemptions attracted remains unknown.',
          cite('mitchell1918', 'Mitchell 1918, 170 nn. 230–31')],
        ['Antitrust ruling', 'Four Southern pipe makers',
          'Their merger was underway before the Supreme Court upheld the ruling against their price agreement.',
          cite('us-pipe-haer', 'O’Connor 1996, 16–18')],
        ['Holding company charter', 'American Tobacco',
          'The company incorporated under New Jersey law and kept its central offices in New York.',
          cite('porter1969', 'Porter 1969, 73–74')]
      ]]
    ];
    return `<figure class="syn-figure syn-contracts" aria-labelledby="compare-institutions-title">
      <figcaption><h2 id="compare-institutions-title">Compare institutions</h2></figcaption>
      <table aria-labelledby="compare-institutions-title">
        <thead><tr><th scope="col">Arrangement</th><th scope="col">Who was involved</th><th scope="col">What the records show</th></tr></thead>
        ${groups.map(([group, rows]) => `<tbody aria-label="${group}">${rows.map(([arrangement, actor, evidence, source]) => `<tr>
          <th scope="row">${arrangement}</th>
          <td><span class="syn-holder">${actor}</span></td>
          <td>${evidence}${source}</td>
        </tr>`).join('')}</tbody>`).join('')}
      </table>
    </figure>`;
  }

  if (sectionId === 'conclusion') {
    return `<figure class="syn-figure syn-tree" aria-label="What employment and factory records reveal">
      <div class="syn-origin"><strong>Southern factory growth</strong></div>
      <div class="syn-paths">
        <div class="syn-path">
          <div class="syn-question">Where were the jobs?</div>
          <div class="syn-terminal">Census tables locate wage earners by region.
            ${cite('bls1947', 'Poulton 1947, 6–7, tables 1–2')}
          </div>
        </div>
        <div class="syn-path">
          <div class="syn-question">Who could change the machinery?</div>
          <ul class="syn-cases">
            <li><strong>Cotton</strong> Machinery-firm employees accounted for about 55% of Massachusetts textile patents in 1910.
              ${cite('sutthiphisal2006', 'Sutthiphisal 2006, PDF 19–21')}</li>
            <li><strong>Pipe</strong> One Birmingham foundry devised a process locally. A rival’s parent directed research from Burlington, New Jersey.
              ${cite('us-pipe-haer', 'O’Connor 1996, 19, 24–32')}</li>
            <li><strong>Cigarettes</strong> Duke’s Durham mechanics improved how leased machines ran.
              ${cite('porter1969', 'Porter 1969, 67–69')}</li>
          </ul>
        </div>
      </div>
      <figcaption>At the next factory opening, ask who can test a design, authorize its use elsewhere and pay for a failed trial.</figcaption>
    </figure>`;
  }

  return '';
}

