function compactCaseEvidence(sectionId) {
  const evidence = {
    cotton: {
      title: 'Mill ownership and loom design followed different paths',
      observations: [
        {
          label: 'Stock and credit',
          claim: 'A subscription recorded a pledge. Some mills paid for machinery partly in shares, which the supplier could sell. A Greenville broker put the cash payment at about two-thirds of the price. A mill could thus order equipment before it had raised the full purchase price. Commission houses advanced credit in exchange for years of cloth sales.',
          sources: [['mitchell1918', 'Mitchell 1918, 149, 205–15']]
        },
        {
          label: 'A design shared across workplaces',
          claim: 'The Northrop loom replaced an empty bobbin without removing the shuttle from the loom. A mill agent in Chicopee designed a filling detector that Draper’s inventors then modified.',
          sources: [['draper1905', 'Draper 1905, 43–44, 49, 71']]
        },
        {
          label: 'What patents capture',
          comparison: `<table class="patent-pairs">
            <caption>US textile employment and patents, 1910 (rounded shares)</caption>
            <thead><tr><th scope="col">Region</th><th scope="col">Employment</th><th scope="col">Patents</th></tr></thead>
            <tbody>
              <tr><th scope="row">Massachusetts</th><td>22%</td><td>42%</td></tr>
              <tr><th scope="row">14-state South</th><td>19%</td><td>7%</td></tr>
            </tbody>
          </table>`,
          claim: 'In Massachusetts, employees of textile machinery firms accounted for about 55 percent of the state’s textile patents in 1910. Southern mill workers could repair or adjust a loom without filing a patent.',
          sources: [['sutthiphisal2006', 'Sutthiphisal 2006, PDF 12–13, 19–20']]
        }
      ]
    },
    pipe: {
      title: 'Where did foundry research take place?',
      observations: [
        {
          label: 'Work inside a foundry',
          claim: 'David Giles developed a revolving casting pit at his Chattanooga works in 1886. The 1906 Atlanta register places American Cast Iron Pipe at a trade meeting. Moore’s later shop tests document its Birmingham design.',
          sources: [['us-pipe-haer', 'O’Connor 1996, 13–16, 30–32'], ['apwa1907', 'APWA 1907, 7, 23']]
        },
        {
          label: 'Research after the merger',
          claim: 'By the 1912–13 review, the combine’s four main Southern works produced about 200,000 tons a year. The review called for larger works at Birmingham and Bessemer. The company transferred research from individual plant managers to Burlington, New Jersey. A Southern plant could gain casting capacity even as its manager lost authority over what to test.',
          sources: [['us-pipe-haer', 'O’Connor 1996, 16–21']]
        },
        {
          label: 'From patent to plant',
          claim: 'The patent shows molten metal entering a rotating mold. Buying the US rights gave the combine a design that its own engineers continued to improve. Early output was up to 15 six-inch pipes per machine-hour. By 1926 the rate had reached 40. O’Connor does not date the installation at the combine’s Birmingham works.',
          sources: [['delavaud1916', 'Sensaud de Lavaud & Arens 1916, fig. 1'], ['us-pipe-haer', 'O’Connor 1996, 22–29, 32']]
        }
      ]
    }
  };
  const chapter = evidence[sectionId];
  if (!chapter) return '';

  return `<section class="argument-strip" aria-labelledby="${sectionId}-evidence-reading">
    <h2 class="argument-caption" id="${sectionId}-evidence-reading">${esc(chapter.title)}</h2>
    <ul class="argument-points">${chapter.observations.map(({ label, comparison, claim, sources }) => `
      <li><strong>${esc(label)}</strong>${comparison || ''}<p>${esc(claim)}</p>
        ${sources.map(([id, locator]) => `<button type="button" class="argument-source" data-source="${esc(id)}">${esc(locator)}</button>`).join(' ')}
      </li>`).join('')}
    </ul>
  </section>`;
}

