function cigaretteEvidence() {
  function sourceButton(id, locator) {
    return `<button class="argument-source" type="button" data-source="${id}">${locator}</button>`;
  }

  const points = [
    ['Making cigarettes', 'Bonsack estimated 100,000 cigarettes in ten hours. Allen &amp; Ginter abandoned its trial in 1883. Actual output depended on keeping the paper feed, paste and cutter in step.',
      [sourceButton('bonsack1881', 'Bonsack 1881, specification 1, 4–5'), sourceButton('porter1969', 'Porter 1969, 67–69')]],
    ['Finding buyers', 'Before the merger, Duke already employed his own buyers at tobacco warehouses. His firm saved on leaf and machine rent, but selling the extra cigarettes drove up costs. In 1889 Duke spent $800,000 on advertising, a fifth of gross sales.',
      [sourceButton('porter1969', 'Porter 1969, 64–70')]],
    ['Sharing control', 'Duke became president when five firms merged in 1890. By late 1898 financiers had joined the board, and Duke was the only founder still serving.',
      [sourceButton('porter1969', 'Porter 1969, 71–75')]]
  ];

  return `<section class="argument-strip" aria-labelledby="argument-cigarettes">
    <h2 class="argument-caption" id="argument-cigarettes">What happened when output outgrew demand?</h2>
    <ul class="argument-points">${points.map(([title, claim, sources]) =>
      `<li><strong>${title}</strong><p>${claim}</p>${sources.join(' ')}</li>`
    ).join('')}</ul>
  </section>`;
}

